create or replace function public.signal_promote_business_staging(p_dataset_key text)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  dataset_row public.signal_datasets;
  source_row public.signal_source_catalog;
  promoted_count integer := 0;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'service_role_required';
  end if;

  select * into dataset_row from public.signal_datasets where dataset_key=p_dataset_key for update;
  if dataset_row.id is null then raise exception 'dataset_not_found'; end if;
  if dataset_row.legal_status <> 'approved' then raise exception 'dataset_not_approved'; end if;

  select * into source_row from public.signal_source_catalog where id=dataset_row.source_id;
  if source_row.id is null or source_row.approval_status <> 'approved' or not source_row.enabled then
    raise exception 'source_not_approved_and_enabled';
  end if;

  update public.signal_datasets set ingestion_status='promoting',updated_at=now() where id=dataset_row.id;

  insert into public.signal_business_phone_records(
    source_id,source_record_id,phone_e164,country_code,business_name,category,locality,source_url,fetched_at,provenance
  )
  select
    dataset_row.source_id,
    coalesce(nullif(s.payload->>'source_record_id',''),s.source_record_fingerprint),
    s.phone_e164,
    s.country_code,
    left(s.payload->>'business_name',300),
    nullif(s.payload->>'category',''),
    nullif(s.payload->>'locality',''),
    nullif(s.payload->>'source_url',''),
    now(),
    jsonb_build_object('pipeline','signal_promote_business_staging','dataset_key',dataset_row.dataset_key,'dataset_id',dataset_row.id,'source_record_fingerprint',s.source_record_fingerprint)
  from public.signal_source_records_staging s
  where s.dataset_id=dataset_row.id
    and s.status='staged'
    and s.record_kind='business_phone'
    and s.phone_e164 ~ '^\+[1-9][0-9]{6,14}$'
    and nullif(trim(s.payload->>'business_name'),'') is not null
  on conflict(source_id,source_record_id,phone_e164) do update set
    country_code=excluded.country_code,
    business_name=excluded.business_name,
    category=excluded.category,
    locality=excluded.locality,
    source_url=excluded.source_url,
    fetched_at=excluded.fetched_at,
    provenance=excluded.provenance;

  get diagnostics promoted_count = row_count;

  update public.signal_source_records_staging
  set status='promoted',promoted_at=now()
  where dataset_id=dataset_row.id
    and status='staged'
    and record_kind='business_phone'
    and phone_e164 ~ '^\+[1-9][0-9]{6,14}$'
    and nullif(trim(payload->>'business_name'),'') is not null;

  update public.signal_datasets set ingestion_status='promoted',updated_at=now() where id=dataset_row.id;

  return jsonb_build_object('datasetKey',dataset_row.dataset_key,'promotedRows',promoted_count,'sourceKey',source_row.source_key);
end
$$;
revoke all on function public.signal_promote_business_staging(text) from public, anon, authenticated;
grant execute on function public.signal_promote_business_staging(text) to service_role;

